import{_ as n,o as i,c as r,b6 as t,mg as a,mh as s,mi as l,mj as o,mk as d,ml as u,mm as h,mn as g,mo as c,mp as m,mq as p,mr as f,ms as b,mt as k,mu as S,mv as w,mw as z,mx as v,my as P,mz as I,mA as _,mB as q,mC as W,mD as D,mE as M,mF as C,mG as A,mH as B,mI as E,mJ as K,mK as T,mL as V,mM as x,mN as N,mO as F,mP as j,mQ as R,mR as y,mS as H,mT as O,mU as U,mV as G}from"./chunks/framework.BUXTSoD9.js";const ne=JSON.parse('{"title":"So bauen Sie das einfachste WeChat Mini Program","description":"","frontmatter":{},"headers":[],"relativePath":"de-de/stage-3/cross-platform/wechat-miniprogram/index.md","filePath":"de-de/stage-3/cross-platform/wechat-miniprogram/index.md"}'),Z={name:"de-de/stage-3/cross-platform/wechat-miniprogram/index.md"};function L(X,e,J,Q,$,Y){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="so-bauen-sie-das-einfachste-wechat-mini-program" tabindex="-1">So bauen Sie das einfachste WeChat Mini Program <a class="header-anchor" href="#so-bauen-sie-das-einfachste-wechat-mini-program" aria-label="Permalink to “So bauen Sie das einfachste WeChat Mini Program”">​</a></h1><h1 id="_1-was-wechat-mini-programs-und-mini-program-entwicklung-sind" tabindex="-1">1. Was WeChat Mini Programs und Mini-Program-Entwicklung sind <a class="header-anchor" href="#_1-was-wechat-mini-programs-und-mini-program-entwicklung-sind" aria-label="Permalink to “1. Was WeChat Mini Programs und Mini-Program-Entwicklung sind”">​</a></h1><p>In diesem Tutorial werden wir einen vollständigen geschlossenen Kreislauf durchlaufen: von einer Idee in Ihrem Kopf zu einem echten Mini Program, das in WeChat per QR-Code gesucht und geöffnet werden kann.</p><p>Bevor wir mit dem Bauen beginnen, müssen wir zwei grundlegende Verständnisse aufbauen.</p><p>Das erste ist das <strong>Wesen</strong>: Was genau ist ein WeChat Mini Program? Wie unterscheidet es sich von einer normalen App oder Website? Warum entscheiden sich so viele Produkte für dieses Format? Nur wenn Sie die Kernlogik verstehen, können Sie beurteilen, ob Ihre Idee zu einem Mini Program passt.</p><p>Das zweite ist der <strong>Pfad</strong>: Wenn Sie sagen &quot;Ich möchte ein Mini Program bauen&quot;, wie sieht der vollständige Pfad von null bis Veröffentlichung aus? Was sind die wichtigsten Knotenpunkte auf diesem Pfad - worüber man bei der Ideenfindung nachdenken muss, wie man die Umgebung einrichtet, wie KI-gestützte Entwicklung die Effizienz verbessert, welche Fallstricke beim Simulator-Debugging auftreten und was Testkonten versus formelle Veröffentlichung jeweils lösen. Wenn Sie diesen Prozess vorher gedanklich durchlaufen, werden Sie bei der Implementierung nicht den Überblick verlieren.</p><p>Nachdem diese beiden Fragen geklärt sind, können wir formell in die Entwicklung einsteigen. Beginnen wir mit der ersten Frage: Was genau ist ein WeChat Mini Program?</p><h2 id="_1-1-wechat-mini-program" tabindex="-1">1.1 WeChat Mini Program <a class="header-anchor" href="#_1-1-wechat-mini-program" aria-label="Permalink to “1.1 WeChat Mini Program”">​</a></h2><p>Ein WeChat Mini Program kann als eine App angesehen werden, die innerhalb von WeChat lebt. Sie müssen nicht in einem App Store suchen, herunterladen oder installieren. Nutzer können in WeChat nach Namen suchen, einen QR-Code scannen oder eine geteilte Karte öffnen und es sofort nutzen. Nach Gebrauch schließen sie es einfach. Es belegt nicht dauerhaft den Startbildschirm oder Speicher des Handys.</p><p>Für reguläre Nutzer lösen Mini Programs viele &quot;kleine Aufgaben&quot;: Sendungsverfolgung, Kaffee bestellen, Bestellungen ansehen, ein kurzes Spiel spielen. Schneller Start und einheitlicher Einstieg innerhalb von WeChat sind seine größten Erlebnismerkmale.</p><p>Für Unternehmen und Entwickler sind Mini Programs ein durchsuchbares und teilbares &quot;kleines App-Format&quot;. Solange Sie sich auf der WeChat Official Platform registrieren, die Einstellungen abschließen und die Überprüfung bestehen, kann Ihr Mini Program allen WeChat-Nutzern zugänglich gemacht werden. Im Vergleich zu traditionellen Apps ist es einfacher, die ersten Nutzer zu gewinnen, da Menschen bereits daran gewöhnt sind, viele Aufgaben in WeChat zu erledigen.</p><p>In diesem Tutorial werden wir kein komplexes Geschäftssystem bauen. Wir wählen ein klassisches Beispiel: das Snake-Spiel. Es ist klein und logisch klar, enthält aber die vollständigen Elemente, die ein Mini Program haben sollte: mehrere Seiten, einfache Interaktionen, Zustandsänderungen, Punktestandsaufzeichnung usw. Es ist perfekt als Ihr erstes Projekt.</p><h2 id="_1-2-wechat-mini-program-entwicklung" tabindex="-1">1.2 WeChat Mini Program Entwicklung <a class="header-anchor" href="#_1-2-wechat-mini-program-entwicklung" aria-label="Permalink to “1.2 WeChat Mini Program Entwicklung”">​</a></h2><p>Nachdem wir verstanden haben, &quot;was Mini Programs sind&quot;, lautet die nächste Frage: Was beinhaltet die Entwicklung eines solchen tatsächlich?</p><p>Sie benötigen ein klares Ziel (zum Beispiel ein Snake-Spiel, das Nutzer jederzeit spielen können), entwerfen die Oberfläche, die Nutzer sehen werden, definieren, was bei verschiedenen Aktionen passieren soll, und veröffentlichen es schließlich.</p><p>In der traditionellen Entwicklung leiten Programmierer normalerweise alle diese Schritte und schreiben viel Code. In der KI-gestützten Entwicklung kann dies klarer aufgeteilt werden: Sie erklären, was Sie wollen, und KI hilft bei den meisten Implementierungsdetails. Das bedeutet für Anfänger, dass die wichtigste Fähigkeit nicht mehr das Auswendiglernen von Syntax ist, sondern das klare Beschreiben von Anforderungen und das Verstehen der KI-Ausgabe.</p><h2 id="_1-3-mehrere-wege-zur-entwicklung-von-wechat-mini-programs" tabindex="-1">1.3 Mehrere Wege zur Entwicklung von WeChat Mini Programs <a class="header-anchor" href="#_1-3-mehrere-wege-zur-entwicklung-von-wechat-mini-programs" aria-label="Permalink to “1.3 Mehrere Wege zur Entwicklung von WeChat Mini Programs”">​</a></h2><p>In echten Projekten verwenden Menschen unterschiedliche technische Routen. Um Sie zu Beginn nicht mit Begriffen zu überfordern, werden wir nur eine grobe Einteilung vornehmen, damit Sie die gängigen Pfade verstehen.</p><p>Der erste Weg ist die direkte Nutzung der offiziellen nativen Funktionen. Nachdem Sie ein Projekt in WeChat DevTools erstellt haben, sehen Sie einen festen Satz von Dateitypen, die zur Beschreibung von Seitenstruktur, Stilen und Logik verwendet werden. Dieser Weg bleibt nah an der offiziellen Dokumentation und bietet starke Kontrolle, aber für Frontend-Einsteiger ist die Lernkurve etwas steiler.</p><p>Der zweite Weg ist die Verwendung von Cross-Plattform-Frameworks wie uni-app. Sie schreiben hauptsächlich webähnlichen Code lokal (z. B. <code>.vue</code>-Dateien), und das Framework konvertiert diesen Code in Formate, die WeChat Mini Programs ausführen können. Der Vorteil ist eine einheitliche Struktur. Wenn Sie später auf anderen Plattformen veröffentlichen (wie H5 oder App), sind die Änderungen relativ gering.</p><p>Basierend auf diesen beiden Methoden konzentriert sich dieses Tutorial auf die Mini-Program-SOP mit KI-gestützten Tools. Zum Beispiel das gesamte Projekt in Trae öffnen und der integrierten KI direkt sagen: &quot;Bitte füge eine Startseite mit Titel und Schaltfläche in dieser Datei hinzu&quot; oder &quot;Bitte erstelle eine Spielseite, die Schlange und Punktestand anzeigt.&quot; Die KI generiert neue Code-Snippets oder ändert/refaktoriert vorhandenen Code basierend auf dem aktuellen Projektkontext.</p><p>Diese drei Wege schließen sich nicht gegenseitig aus. Sie können absolut in einem uni-app-Projekt bauen und gleichzeitig Trae KI für den größten Teil der Codierungsarbeit nutzen. Der Schlüssel ist nicht, eine Methode auszuwählen, sondern zu wissen, wo Sie gerade stehen und welche Tools zur Verfügung stehen.</p><h2 id="_1-4-in-diesem-artikel-behandelte-wechat-mini-program-schritte-vorschau" tabindex="-1">1.4 In diesem Artikel behandelte WeChat Mini Program Schritte (Vorschau) <a class="header-anchor" href="#_1-4-in-diesem-artikel-behandelte-wechat-mini-program-schritte-vorschau" aria-label="Permalink to “1.4 In diesem Artikel behandelte WeChat Mini Program Schritte (Vorschau)”">​</a></h2><p>Dieses Tutorial folgt einem Rhythmus von <strong>Umgebung bis Endprodukt</strong>. Am Beispiel von Snake und Trae-Vibecoding-Stil unterteilen wir den Prozess in eine wiederverwendbare Route. In späteren Kapiteln werden Sie diese Phasen durchlaufen:</p><ol><li>Konzeptionelle Grundlagen schaffen: Verstehen, was Mini Programs sind, welche gängigen Entwicklungsmethoden es gibt und für wen dieses Snake-Mini-Program gedacht ist und in welchen Szenarien es verwendet wird.</li><li>Umgebung vorbereiten: Mini-Program-Konto registrieren, HBuilderX, Trae und WeChat DevTools installieren, dann ein grundlegendes Projektgerüst mit HBuilderX erstellen, das in WeChat DevTools ausgeführt werden kann und zunächst die einfachste Seite anzeigt.</li><li>Formelle Entwicklung beginnen: Projekt in Trae öffnen, den Vibecoding-Dialog mit KI nutzen, um Schritt für Schritt Startseiten- und Spielseitenlayout zu generieren und Kernspielmechaniken wie Schlangenbewegung, Fressen und Spielende zu implementieren.</li><li>Nachdem die Kernfunktionen laufen, lernen, KI als &quot;Debugging- und Refactoring-Partner&quot; zu nutzen: Sie bitten, Bugs zu diagnostizieren, die Struktur aufzuräumen, wenn der Code unübersichtlich wird, und schrittweise Details wie Start/Pause, Highscore-Aufzeichnung und UI-Politur hinzuzufügen.</li><li>Veröffentlichung beginnen: Projekt in eine von WeChat erkennbare Version bauen, auf echten Geräten in WeChat DevTools vorschauen und testen, zuerst mit Testkonto und Erfahrungsversion zur Prozessvalidierung starten, dann Registrierung und Überprüfung abschließen, bevor formell veröffentlicht wird, damit andere Ihr Mini Program suchen und spielen können.</li></ol><p>Dieser Abschnitt zeichnet nur die vollständige Karte und klappert noch keine Befehle oder Codedetails aus. Merken Sie sich vorerst diese 5 Schritte: <strong>Verstehen -&gt; Umgebung einrichten -&gt; Vibecoding-Entwicklung -&gt; Debuggen und Polishen -&gt; Bauen und Veröffentlichen</strong>. Spätere Kapitel werden in jeden Schritt hineinzoomen und zeigen, was vorzubereiten ist, was Sie der KI sagen sollen und welche Ergebnisse Sie auf dem Bildschirm sehen sollten.</p><h1 id="_2-umgebungsvorbereitung" tabindex="-1">2. Umgebungsvorbereitung <a class="header-anchor" href="#_2-umgebungsvorbereitung" aria-label="Permalink to “2. Umgebungsvorbereitung”">​</a></h1><p>Bevor wir eine Zeile Code schreiben, bereiten wir zuerst die Umgebung vor. Das Ziel dieses Teils ist sicherzustellen, dass Sie nicht mehr bei <strong>wo Tools herunterladen und warum Dinge nicht laufen</strong> stecken bleiben, damit Sie sich direkt auf KI-Dialog und Anforderungsimplementierung konzentrieren können.</p><p>Wenn Sie einen Browser öffnen, Dateien herunterladen und Installationsprogramme per Doppelklick ausführen können, können Sie diesen Abschnitt abschließen.</p><h2 id="_2-1-drei-in-diesem-tutorial-verwendete-tools" tabindex="-1">2.1 Drei in diesem Tutorial verwendete Tools <a class="header-anchor" href="#_2-1-drei-in-diesem-tutorial-verwendete-tools" aria-label="Permalink to “2.1 Drei in diesem Tutorial verwendete Tools”">​</a></h2><p>Für die Snake-Mini-Program-Entwicklung verwenden wir drei Tools zusammen, jedes mit unterschiedlichen Aufgaben:</p><ol><li>Das erste ist Trae. Betrachten Sie es als einen KI-integrierten Code-Editor. Es kann Projektdateien wie eine normale IDE öffnen und Sie auch in natürlicher Sprache mit KI chatten, um Code zu generieren, zu ändern und zu erklären. Die meisten &quot;Mini-Program mit KI bauen&quot;-Operationen in diesem Tutorial finden in Trae statt. Laden Sie die neueste Version von <a href="https://www.trae.cn" target="_blank" rel="noreferrer">https://www.trae.cn</a> herunter.</li><li>Das zweite ist HBuilderX. Es hat starke Unterstützung für Vue und uni-app und bietet vorgefertigte Mini-Program-Vorlagen. Wir verwenden es, um &quot;mit einem Klick&quot; ein Basis-Mini-Program-Projekt zu generieren - das ist die Grundlage, bevor es an Trae + KI zur weiteren Iteration übergeben wird. Download von <a href="https://www.dcloud.io/hbuilderx.html" target="_blank" rel="noreferrer">https://www.dcloud.io/hbuilderx.html</a>.</li><li>Das dritte ist WeChat DevTools. Dieses offizielle Tool wird zur Entwicklung und Vorschau von Mini Programs verwendet. Es führt Ihr Projekt auf dem Desktop aus und unterstützt echtes Geräte-Debugging auf dem Handy. Download von <a href="https://developers.weixin.qq.com/miniprogram/dev/devtools/download.html" target="_blank" rel="noreferrer">https://developers.weixin.qq.com/miniprogram/dev/devtools/download.html</a>.</li></ol><p>Kurz gesagt: HBuilderX erstellt schnell das Basisprojekt, Trae hilft Ihnen beim Codieren mit KI, und WeChat DevTools zeigt das tatsächlich laufende Mini Program.</p><h2 id="_2-2-wechat-official-platform-konto-registrieren-und-appid-erhalten" tabindex="-1">2.2 WeChat Official Platform Konto registrieren und AppID erhalten <a class="header-anchor" href="#_2-2-wechat-official-platform-konto-registrieren-und-appid-erhalten" aria-label="Permalink to “2.2 WeChat Official Platform Konto registrieren und AppID erhalten”">​</a></h2><p>Mit den Tools bereit benötigen Sie noch eine <strong>Mini-Program-Identität</strong>, die auf der WeChat Official Platform erstellt wird. Wenn Sie noch nie ein Mini Program registriert haben, folgen Sie dieser Reihenfolge:</p><ol><li>Geben Sie <a href="https://mp.weixin.qq.com" target="_blank" rel="noreferrer">https://mp.weixin.qq.com</a> in Ihrem Browser ein, öffnen Sie die WeChat Official Platform und melden Sie sich durch Scannen des QR-Codes mit WeChat an.</li></ol><p><img src="'+a+'" alt=""></p><ol start="2"><li>Wählen Sie &quot;Mini Program&quot; auf der Startseite und schließen Sie die Registrierungsaufforderungen ab, einschließlich E-Mail, Telefonnummer und Entitätstyp (Einzelne oder Unternehmen). <img src="'+s+'" alt=""></li><li>Nach erfolgreicher Registrierung betreten Sie das Backend, finden Sie &quot;Development Management&quot; oder &quot;Development Settings&quot; und Sie sehen eine eindeutige ID namens AppID. Dies ist Ihre Mini-Program-Identität und wird später in der Projektkonfiguration verwendet.</li></ol><p><img src="'+l+'" alt=""></p><p>Es wird empfohlen, die AppID an einem leicht findbaren Ort zu speichern. In späteren Abschnitten werden wir diesen Wert direkt eintragen, um das lokale Projekt Ihrem Online-Mini-Program zuzuordnen.</p><h2 id="_2-3-wechat-devtools-installieren" tabindex="-1">2.3 WeChat DevTools installieren <a class="header-anchor" href="#_2-3-wechat-devtools-installieren" aria-label="Permalink to “2.3 WeChat DevTools installieren”">​</a></h2><p>Als Nächstes benötigen wir einen Ort, um Mini Programs tatsächlich auszuführen und eine Vorschau anzuzeigen. Genau dafür sind die WeChat DevTools gedacht.</p><ol><li>Besuchen Sie die Download-Seite <a href="https://developers.weixin.qq.com/miniprogram/dev/devtools/download.html" target="_blank" rel="noreferrer">https://developers.weixin.qq.com/miniprogram/dev/devtools/download.html</a>. Auf dieser Seite sehen Sie Versionen für verschiedene Betriebssysteme. Wählen Sie normalerweise die stabile Version, die zu Ihrem System passt, wie Windows 64-Bit oder macOS.</li><li>Nach dem Download doppelklicken Sie auf das Installationsprogramm und folgen dem Assistenten Schritt für Schritt. Im Zweifelsfall die Standardoptionen beibehalten.</li><li>Nach der Installation starten Sie WeChat DevTools vom Desktop oder Startmenü. Beim ersten Start wird ein QR-Code angezeigt und Sie werden aufgefordert, mit WeChat zu scannen. Scannen und autorisieren Sie, um die Hauptoberfläche zu betreten.</li></ol><p><img src="'+o+'" alt=""><img src="'+d+'" alt=""></p><p>Später, wenn die Projektdateien in Trae bereit sind, werden wir das erstellte Mini Program in WeChat DevTools importieren und hier die echten Laufergebnisse ansehen.</p><h2 id="_2-4-trae-und-hbuilderx-vorbereiten" tabindex="-1">2.4 Trae und HBuilderX vorbereiten <a class="header-anchor" href="#_2-4-trae-und-hbuilderx-vorbereiten" aria-label="Permalink to “2.4 Trae und HBuilderX vorbereiten”">​</a></h2><p>Installieren Sie schließlich die beiden Tools, die für das eigentliche Codieren verwendet werden: Trae und HBuilderX.</p><p>Sie können <strong>Trae zuerst installieren</strong>. Besuchen Sie <a href="https://www.trae.cn" target="_blank" rel="noreferrer">https://www.trae.cn</a> im Browser und laden Sie die richtige Version für Ihr Betriebssystem herunter. Die Installation erfolgt wie bei normaler Software: Doppelklicken Sie auf das Installationsprogramm und folgen Sie den Anweisungen. Nach der Installation erhalten Sie eine IDE, die lokale Ordner öffnen, Code inspizieren und mit KI chatten kann. Alle späteren Vibecoding-Schritte finden hier statt.</p><p><img src="'+u+'" alt=""></p><p><strong>Installieren Sie dann HBuilderX</strong>. Besuchen Sie <a href="https://www.dcloud.io/hbuilderx.html" target="_blank" rel="noreferrer">https://www.dcloud.io/hbuilderx.html</a> und laden Sie das Paket für Ihr Betriebssystem herunter. HBuilderX ist leichtgewichtig und startet schnell. Nach der Installation können Sie kurz die Oberfläche betrachten; kein tiefer Funktionsstudium jetzt nötig. In späteren Kapiteln verwenden wir es, um eine uni-app-Mini-Program-Vorlage als Projektstartpunkt zu erstellen.</p><p><img src="'+h+'" alt=""></p><p>Nach Abschluss dieses Abschnitts ist Ihre Umgebung vollständig: Sie haben ein Mini-Program-Konto + AppID, ein Laufzeit-Vorschautool und eine KI-Coding-IDE. Als Nächstes beginnen wir mit <strong>dem Erstellen des ersten Projektgerüsts</strong> und lassen diese Tools wirklich laufen.</p><h2 id="_2-5-basisdateien-vorbereiten" tabindex="-1">2.5 Basisdateien vorbereiten <a class="header-anchor" href="#_2-5-basisdateien-vorbereiten" aria-label="Permalink to “2.5 Basisdateien vorbereiten”">​</a></h2><ol><li>Klicken Sie auf &quot;Neues Projekt&quot;.</li></ol><p><img src="'+g+'" alt=""></p><ol start="2"><li>Wählen Sie die Standardvorlage, setzen Sie den Mini-Program-Namen, wählen Sie den Speicherpfad und klicken Sie dann auf Erstellen in der unteren rechten Ecke:</li></ol><p><img src="'+c+'" alt=""></p><ol start="3"><li>Der Bildschirm zur erfolgreichen Erstellung erscheint:</li></ol><p><img src="'+m+'" alt=""></p><ol start="4"><li>Finden Sie dann diesen Ordner im Dateisystem, öffnen Sie ihn in Trae und Sie sehen, dass die Grundlagendateien alle bereit sind:</li></ol><p><img src="'+p+'" alt=""></p><h1 id="_3-mini-program-entwicklung" tabindex="-1">3. Mini Program Entwicklung <a class="header-anchor" href="#_3-mini-program-entwicklung" aria-label="Permalink to “3. Mini Program Entwicklung”">​</a></h1><p>In den ersten beiden Teilen haben wir bereits geklärt, &quot;was Mini Programs sind&quot; und &quot;wie man Tools und Umgebung einrichtet.&quot; Ab diesem Abschnitt betreten wir die Praxis: nicht nur Konzepte, sondern KI hilft Ihnen tatsächlich, das Snake-Mini-Program von null auf zu bauen.</p><p>In diesem Abschnitt werden Sie eine vollständige SOP für die Entwicklungsphase durchlaufen, ungefähr einschließlich:</p><ol><li>Öffnen Sie das aktuelle Projekt in Trae und geben Sie KI Ihre erste vollständige Anweisung, damit sie eine ausführbare Snake-Version basierend auf dem aktuellen Gerüst entwirft und implementiert.</li><li>Lassen Sie Trae echte Projektdateien direkt ändern, nicht nur &quot;Beispielcode&quot; ausgeben, und lernen, Rollback zu verwenden, um den vorherigen Zustand bei Bedarf wiederherzustellen.</li><li>Kehren Sie zu HBuilderX und WeChat DevTools zurück, führen Sie es im Mini-Program-Simulator aus und spielen Sie diese Version im Simulator, um von der &quot;Code-Perspektive&quot; zur &quot;Nutzer-Perspektive&quot; zu wechseln.</li><li>Basierend auf den Spielergebnissen weiterhin Änderungen in natürlicher Sprache vorschlagen und KI die Steuerung von schaltflächenbasiert zu joystickbasiert iterieren lassen, während Sie eine vollständige Schleife von &quot;Problem finden -&gt; Problem beschreiben -&gt; KI repariert -&gt; erneut verifizieren&quot; erleben.</li></ol><p>Sie können wählen, jede Seite und Schaltfläche vor der Entwicklung zu entwerfen. Aber für komplette Anfänger ist Interface- und Interaktionsdesign selbst auch ein neues Gebiet (später werden wir KI-gestütztes Design zeigen). In dieser Runde nutzen wir absichtlich einen anderen Weg: zuerst anfangen - KI eine ausführbare Version generieren lassen, dann schrittweise verfeinern, indem Effekte betrachtet und in natürlicher Sprache gechattet wird.</p><h2 id="_3-1-anforderungen-in-einem-klartext-erklaren-geben-sie-trae-den-ersten-master-prompt" tabindex="-1">3.1 Anforderungen in einem Klartext erklären: Geben Sie Trae den ersten &quot;Master-Prompt&quot; <a class="header-anchor" href="#_3-1-anforderungen-in-einem-klartext-erklaren-geben-sie-trae-den-ersten-master-prompt" aria-label="Permalink to “3.1 Anforderungen in einem Klartext erklären: Geben Sie Trae den ersten &quot;Master-Prompt&quot;”">​</a></h2><p>Nachdem ich das vorbereitete Mini-Program-Projekt in Trae geöffnet hatte, stürzte ich mich nicht auf eine bestimmte Zeile. Stattdessen sagte ich dem integrierten KI-Assistenten:</p><p><strong>Ich gab KI einen Befehl: Basierend auf dem aktuellen Framework ein Snake-Mini-Program bauen. Bitte entwerfen Sie dieses Mini Program und schreiben Sie mir einen Prompt.</strong></p><p>Mit anderen Worten, ich bat sie nicht, &quot;Schritt für Schritt eine Funktion zu schreiben.&quot; Ich warf zuerst ein vollständiges Ziel heraus, ließ KI helfen zu planen, und KI plante nicht nur, sondern landete auch direkt die erste Implementierung.</p><p>Nach Erhalt dieser Anweisung liest Trae die aktuelle Projektstruktur, bestimmt, wo Seiten hinzuzufügen sind und wo Logik hinzuzufügen ist, und ändert direkt Projektdateien/Code. Sie müssen keinen Code von Hand schreiben oder manuell Ordner erstellen/ändern.</p><h2 id="_3-2-ki-echten-code-automatisch-andern-lassen-nicht-manuell-coden" tabindex="-1">3.2 KI echten Code automatisch ändern lassen, nicht manuell coden <a class="header-anchor" href="#_3-2-ki-echten-code-automatisch-andern-lassen-nicht-manuell-coden" aria-label="Permalink to “3.2 KI echten Code automatisch ändern lassen, nicht manuell coden”">​</a></h2><p>Wenn Sie diese Anweisung in Trae ausführen, betritt KI einen &quot;Projektbearbeitungs&quot;-Ablauf. Während dieses Prozesses können Sie folgende Punkte beobachten:</p><ol><li>Sie erklärt ihr Denken im Chat-Bereich, zum Beispiel in welche Verzeichnisse sie Seiten hinzufügen wird und wie sie die Spiellogik organisieren wird.</li></ol><p><img src="'+f+'" alt=""><img src="'+b+'" alt=""></p><ol start="2"><li>Sie bearbeitet echte Projektdateien direkt, anstatt nur &quot;Beispielcode&quot; zum Kopieren und Einfügen zu geben.</li><li>Nach Abschluss gibt Trae eine kurze Zusammenfassung aus, die Ihnen sagt, welche Dateien geändert wurden und was getan wurde.</li></ol><p>Wenn Sie mit dieser Runde nicht zufrieden sind (oder denken, dass etwas falsch ist), keine Panik. Trae bietet Rollback oben links außerhalb des Chat-Feldes. Sie können den Projektzustand vor dieser Anweisung mit einem Klick wiederherstellen - wie ein sicherer Rückgängig-Schlüssel.</p><p><img src="'+k+'" alt=""></p><p><img src="'+S+'" alt=""></p><h2 id="_3-3-effekte-in-hbuilderx-und-wechat-devtools-ansehen" tabindex="-1">3.3 Effekte in HBuilderX und WeChat DevTools ansehen <a class="header-anchor" href="#_3-3-effekte-in-hbuilderx-und-wechat-devtools-ansehen" aria-label="Permalink to “3.3 Effekte in HBuilderX und WeChat DevTools ansehen”">​</a></h2><p>Nachdem KI die erste Entwicklungsrunde abgeschlossen hat, wurde Code in das Projekt geschrieben, aber Sie haben den echten spielerseitigen Effekt noch nicht gesehen. Als Nächstes müssen wir es ausführen.</p><p>Spezifische Operation: Gehen Sie zurück zu HBuilderX, finden Sie das obere Menü &quot;Run&quot;, wählen Sie &quot;Run to Mini Program Simulator&quot; -&gt; &quot;WeChat DevTools.&quot; Dies löst den Projekt-Build aus und öffnet das Ergebnis in WeChat DevTools.</p><p><img src="'+w+'" alt=""></p><p>Das Ausgabe-Panel unten zeigt den Build-Prozess. Wenn der Endzustand &quot;ready&quot; ohne Fehler ist, war der Build erfolgreich. Wechseln Sie dann zu WeChat DevTools, um UI und Funktionen dieser Version zu prüfen.</p><p><img src="'+z+'" alt=""></p><p>In den meisten Fällen öffnet HBuilderX WeChat DevTools automatisch und Sie können das aktualisierte Mini Program direkt sehen. Wenn nicht automatisch geöffnet, tun Sie Folgendes:</p><ol><li>Stoppen Sie den aktuellen Lauf in HBuilderX zuerst.</li><li>Starten Sie WeChat DevTools manuell und halten Sie es geöffnet.</li><li>Klicken Sie in HBuilderX erneut auf &quot;Run -&gt; Run to Mini Program Simulator -&gt; WeChat DevTools.&quot;</li></ol><p>Dann können Sie das Vibecoding-Mini-Program in WeChat DevTools sehen:</p><p><img src="'+v+'" alt=""></p><h2 id="_3-4-naturliche-sprache-verwenden-um-wiederholt-anzupassen-bis-zufrieden" tabindex="-1">3.4 Natürliche Sprache verwenden, um wiederholt anzupassen, bis zufrieden <a class="header-anchor" href="#_3-4-naturliche-sprache-verwenden-um-wiederholt-anzupassen-bis-zufrieden" aria-label="Permalink to “3.4 Natürliche Sprache verwenden, um wiederholt anzupassen, bis zufrieden”">​</a></h2><p>In dieser Praxis hat KI anfangs ein schaltflächengesteuertes Snake generiert: vier Richtungsschaltflächen auf dem Bildschirm, und die Schlange ändert die Richtung beim Klicken. Es ist vollständig spielbar, aber ich persönlich bevorzuge Joystick-Steuerung. Für Ihre Änderungswünsche (nicht nur Funktionen, sondern auch UI-Design und Layout; wenn Sie Erfahrung haben, können Sie KI sogar bitten, externe Modell-APIs oder Datenbanken zu integrieren) gilt erneut: Sie müssen Anforderungen nur in natürlicher Sprache beschreiben.</p><p>Das ist der Kernvorteil von Vibecoding: Sie müssen nicht in den Code eintauchen für Event-Binding oder Koordinatenlogik. Sie sagen KI direkt, was Sie wollen. Zum Beispiel können Sie im Trae-Chat schreiben:</p><p>Ersetzen Sie Schaltflächen durch Joystick-Steuerung. Wenn der Benutzer den Joystick loslässt, soll die Schlange in die aktuelle Richtung weiterlaufen, bis zur nächsten Joystick-Aktion.</p><p>Solange die Anforderung klar ist, lokalisiert KI automatisch die Zieldateien und ändert Steuerungsstile, Interaktionsbindungen und Richtungsbehandlungslogik.</p><p><img src="'+P+'" alt=""></p><p>Kehren Sie nach der Änderung zu WeChat DevTools zurück, um zu prüfen. Wenn Änderungen nicht sofort sichtbar sind, klicken Sie auf &quot;Run&quot; in DevTools oder aktualisieren Sie das Vorschaufenster, um den neuesten Build anzuwenden. Wenn immer noch nicht aktualisiert, stoppen Sie den Lauf in HBuilderX und führen Sie erneut zum Simulator aus, dann können Sie das aktualisierte Mini Program sehen:</p><p><img src="'+I+'" alt=""></p><h2 id="_3-5-was-tun-bei-problemen-weiterhin-in-naturlicher-sprache-kommunizieren" tabindex="-1">3.5 Was tun bei Problemen: Weiterhin in natürlicher Sprache kommunizieren <a class="header-anchor" href="#_3-5-was-tun-bei-problemen-weiterhin-in-naturlicher-sprache-kommunizieren" aria-label="Permalink to “3.5 Was tun bei Problemen: Weiterhin in natürlicher Sprache kommunizieren”">​</a></h2><p>KI-generierte Versionen sind nicht immer beim ersten Mal perfekt. Sie können Folgendes feststellen:</p><ul><li>Laufzeitfehler und die App lässt sich nicht öffnen;</li><li>Funktionen größtenteils korrekt, aber Details weichen von Ihren Erwartungen ab;</li><li>UI nutzbar, aber noch nicht ansprechend oder komfortabel genug.</li></ul><p>In diesen Momenten müssen Sie nicht blind selbst Code bearbeiten. Beschreiben Sie Probleme direkt dem Trae KI-Assistenten in natürlicher Sprache, zum Beispiel:</p><p>&quot;Joystick-Steuerung funktioniert jetzt, aber die Schlange stoppt manchmal plötzlich. Bitte überprüfen Sie die aktuelle Implementierung.&quot; Oder: &quot;Das Spiel ist jetzt spielbar, aber das Interface wirkt überfüllt. Ich möchte mehr vertikalen Abstand auf dem Handy. Bitte passen Sie das Layout an.&quot;</p><p>KI wird den aktuellen Projektkontext + Ihre Beschreibung nutzen und dann Code-Änderungen direkt bereitstellen und anwenden. Wenn das Ergebnis schlechter wird oder die Richtung falsch ist, können Sie immer noch zur vorherigen stabilen Version zurückrollen und eine andere Formulierung versuchen.</p><p>Durch mehrere solcher Runden können Sie von der &quot;groben ersten Version&quot; zu einem joystickbasierten Snake polieren, das näher an Ihren Präferenzen liegt. Zum Beispiel gab ich ein Stilreferenzbild und bat KI, den UI-Stil entsprechend anzupassen:</p><p><img src="'+_+'" alt=""></p><h2 id="_3-6-endergebnis-und-abschnittszusammenfassung" tabindex="-1">3.6 Endergebnis und Abschnittszusammenfassung <a class="header-anchor" href="#_3-6-endergebnis-und-abschnittszusammenfassung" aria-label="Permalink to “3.6 Endergebnis und Abschnittszusammenfassung”">​</a></h2><p>Nach wiederholten Runden von <strong>natürlicher Sprachbeschreibung -&gt; KI-Änderung -&gt; Vorschau in WeChat DevTools -&gt; weitere Feinjustierung</strong> erhielt ich dieses Ergebnis:</p><ul><li>vollständige Spielseite;</li><li>Schlange bewegt sich flüssig und frisst Futter;</li><li>Joystick-Steuerung unterstützt;</li><li>läuft korrekt im Mini-Program-Simulator.</li></ul><p>Beispiele für das Endprodukt:</p><p><img src="'+q+'" alt=""><img src="'+W+'" alt=""><img src="'+D+'" alt=""></p><p>In diesem Abschnitt haben Sie einen vollständigen geschlossenen Kreislauf gesehen:</p><ol><li>In Trae ließ eine klare Anweisung KI die erste Snake-Mini-Program-Version bauen;</li><li>Mit HBuilderX + WeChat DevTools den echten Effekt aus der Nutzerperspektive validieren;</li><li>Weiterhin Änderungen in natürlicher Sprache vorschlagen, KI Funktions- und UI-Optimierung überlassen;</li><li>Wenn Probleme auftreten, Rollback + Neustart verwenden, um den Prozess sicher zu halten.</li></ol><p>Als Nächstes können Sie denselben Rhythmus für Ihre eigenen Ideen verwenden: nicht beschränkt auf Snake, sondern auch Utility-Mini-Programs, Veranstaltungsseiten oder echte Geschäftsprototypen. Ihre Hauptaufgabe ist es, klar zu denken und klar zu beschreiben. Lassen Sie KI und Tools den Rest erledigen.</p><h1 id="_4-mini-program-veroffentlichung" tabindex="-1">4. Mini Program Veröffentlichung <a class="header-anchor" href="#_4-mini-program-veroffentlichung" aria-label="Permalink to “4. Mini Program Veröffentlichung”">​</a></h1><p>In den vorherigen drei Kapiteln haben wir den vollständigen Ablauf von <strong>Umgebungseinrichtung</strong> -&gt; <strong>KI-gestützte Entwicklung</strong> -&gt; <strong>Snake im lokalen Simulator ausführen</strong> abgeschlossen.</p><p>Ab diesem Kapitel wird die Schlüsselfrage: <strong>Wie veröffentliche ich dieses Werk wirklich in WeChat, damit es nicht nur ein Spielzeug ist, sondern ein nutzbares Mini Program?</strong></p><p>Um die Schwierigkeit zu reduzieren, nehmen wir zuerst den <strong>kürzesten geschlossenen Kreislauf</strong>: nur als <strong>Test-/Erfahrungsversion</strong> für sich selbst und einige Teammitglieder veröffentlichen. Nachdem Funktion und Erlebnis stabil sind, dann zur formellen öffentlichen Veröffentlichung übergehen.</p><p>Dieses Kapitel behandelt zuerst 4.1, um den kürzesten Pfad für den <strong>Erfahrungsversions-Start</strong> abzuschließen. Formelle Veröffentlichung für alle Nutzer wird in 4.2 erklärt.</p><h2 id="_4-1-kurzeste-sop-als-erfahrungsversion-starten" tabindex="-1">4.1 Kürzeste SOP - Als Erfahrungsversion starten <a class="header-anchor" href="#_4-1-kurzeste-sop-als-erfahrungsversion-starten" aria-label="Permalink to “4.1 Kürzeste SOP - Als Erfahrungsversion starten”">​</a></h2><p>Das Ziel dieses Unterabschnitts ist nur eins: Sie Ihr Snake-Mini-Program in WeChat als <strong>Erfahrungsversion</strong> öffnen zu lassen.</p><p>Der gesamte Ablauf umfasst vier Aufgaben:</p><ol><li>Finden und bestätigen Sie Ihre AppID in der WeChat Official Platform.</li><li>Konfigurieren Sie diese AppID in Ihrem Projekt.</li><li>Laden Sie die aktuelle Version in WeChat DevTools hoch.</li><li>Kehren Sie zur Official Platform zurück und setzen Sie diese hochgeladene Version als &quot;Experience Version.&quot;</li></ol><p>Gehen wir in dieser Reihenfolge vor.</p><h3 id="_4-1-1-appid-in-der-wechat-official-platform-bestatigen" tabindex="-1">4.1.1 AppID in der WeChat Official Platform bestätigen <a class="header-anchor" href="#_4-1-1-appid-in-der-wechat-official-platform-bestatigen" aria-label="Permalink to “4.1.1 AppID in der WeChat Official Platform bestätigen”">​</a></h3><p>Erster Schritt: Bestätigen Sie Ihre Mini-Program-AppID in der WeChat Official Platform.</p><p>Sie haben dies bereits einmal in <strong>Abschnitt 2 Umgebungseinrichtung</strong> getan. Hier verwenden wir es tatsächlich.</p><ol><li>Besuchen Sie <code>https://mp.weixin.qq.com</code> und melden Sie sich in Ihrem Mini-Program-Backend an.</li><li>Finden Sie &quot;Development Management&quot; im linken Menü und betreten Sie dann &quot;Development Settings.&quot;</li><li>Oben finden Sie den Bereich &quot;Developer ID&quot;. Dort gibt es eine Zeile &quot;AppID (Mini Program ID)&quot; - das ist Ihre eindeutige ID.</li></ol><p>Diese ID muss exakt mit der Projektkonfiguration übereinstimmen. Andernfalls sieht WeChat sie als eine andere App-Identität und Vorschau/Veröffentlichung werden fehlschlagen.</p><p><img src="'+M+'" alt=""></p><h3 id="_4-1-2-appid-im-projekt-eintragen" tabindex="-1">4.1.2 AppID im Projekt eintragen <a class="header-anchor" href="#_4-1-2-appid-im-projekt-eintragen" aria-label="Permalink to “4.1.2 AppID im Projekt eintragen”">​</a></h3><p>Zweiter Schritt: Schreiben Sie diese AppID in die Projektkonfiguration, damit der lokale Build Ihrem offiziellen Mini-Program-Konto zugeordnet wird.</p><p>Wenn Ihr Projekt die uni-app-Vorlage verwendet, tun Sie Folgendes:</p><ol><li>Öffnen Sie HBuilderX und laden Sie das Snake-Projekt.</li><li>Finden Sie <code>manifest.json</code> im Dateibaum und öffnen Sie es.</li><li>Scrollen Sie zu &quot;WeChat Mini Program Configuration&quot; und Sie sehen ein Eingabefeld wie &quot;WeChat Mini Program AppID.&quot;</li><li>Fügen Sie die von der Official Platform kopierte AppID exakt ein und speichern Sie die Datei. <img src="'+C+'" alt=""></li></ol><p>Jetzt hat Ihr lokales Projekt diese Mini-Program-Identität beansprucht. Als Nächstes, wenn Sie aus WeChat DevTools hochladen, wird es unter dieser AppID aufgezeichnet.</p><h3 id="_4-1-3-eine-version-in-wechat-devtools-hochladen" tabindex="-1">4.1.3 Eine Version in WeChat DevTools hochladen <a class="header-anchor" href="#_4-1-3-eine-version-in-wechat-devtools-hochladen" aria-label="Permalink to “4.1.3 Eine Version in WeChat DevTools hochladen”">​</a></h3><p>Wir haben das Projekt bereits in WeChat DevTools zur Simulatorvorschau ausgeführt.</p><p>Jetzt machen wir: &quot;den aktuellen Code als Version verpacken und zum Server hochladen.&quot;</p><p>Schritte:</p><ol><li>Klicken Sie in der oberen rechten Symbolleiste von WeChat DevTools auf &quot;Upload.&quot;</li><li>Im Popup zwei Schlüsselfelder ausfüllen: <ol><li>Versionsnummer: zum Beispiel <code>1.0.0</code> (nur Ziffern und Punkte).</li><li>Projektnotiz: kurze Beschreibung, wie &quot;Kernspielmechanik abgeschlossen.&quot;</li></ol></li><li>Bestätigen und auf &quot;Upload&quot; klicken. Das Ausgabe-Panel zeigt den Build-Prozess. Wenn alle Schritte grün werden und der Upload abschließt, wurde diese Version erfolgreich an den WeChat-Server übermittelt.</li></ol><p><img src="'+A+'" alt=""></p><p><img src="'+B+'" alt=""></p><p><img src="'+E+'" alt=""><img src="'+K+'" alt=""></p><h3 id="_4-1-4-hochgeladene-version-im-backend-als-erfahrungsversion-setzen" tabindex="-1">4.1.4 Hochgeladene Version im Backend als Erfahrungsversion setzen <a class="header-anchor" href="#_4-1-4-hochgeladene-version-im-backend-als-erfahrungsversion-setzen" aria-label="Permalink to “4.1.4 Hochgeladene Version im Backend als Erfahrungsversion setzen”">​</a></h3><p>Das Hochladen sendet den Code nur an die WeChat-Seite. Sie müssen dem System noch mitteilen: &quot;Dies ist eine Erfahrungsversion.&quot;</p><p>Letzter Schritt: Kehren Sie zum Official Platform Backend zurück und schließen Sie die Schleife.</p><ol><li><p>Öffnen Sie <code>https://mp.weixin.qq.com</code> und betreten Sie das Mini-Program-Backend.</p></li><li><p>Finden Sie im linken Menü &quot;Management&quot; -&gt; &quot;Version Management.&quot;</p></li><li><p>Im Abschnitt &quot;Development Version&quot; sollten Sie die hochgeladene Version sehen: Version <code>1.0.0</code>, Ihre Notiz und den gerade hochgeladenen Zeitstempel.</p></li><li><p>Auf der rechten Seite dieser Zeile verwenden Sie das Dropdown/Aktionsfeld, um &quot;Set as Experience Version&quot; zu wählen und die Aktion zu bestätigen. Vor diesem Schritt stellen Sie sicher, dass Ihre Hauptkategorie auf der Startseite/Kategorieeinstellungen konfiguriert ist.</p><p><img src="'+T+'" alt=""></p><p><img src="'+V+'" alt=""></p></li></ol><p>Nach Abschluss wird diese Version zu Ihrer Mini-Program &quot;Erfahrungsversion.&quot; Sie können im Backend einen Erfahrungs-QR-Code generieren oder sich selbst/das Team als Erfahrungsmitglieder hinzufügen und dann in WeChat für Echtgerät-Tests scannen.</p><p>An diesem Punkt haben wir die kürzeste Schleife vom lokalen Projekt zum Teststart abgeschlossen:</p><p>Sie müssen nicht sofort für alle WeChat-Nutzer öffnen. In einem sicheren Rahmen zuerst das echte Mini Program in der echten WeChat-Umgebung laufen lassen. Das reicht für Funktionstests, Feedback-Sammlung und Iteration.</p><h2 id="_4-2-formelle-veroffentlichung-des-mini-programs" tabindex="-1">4.2 Formelle Veröffentlichung des Mini Programs <a class="header-anchor" href="#_4-2-formelle-veroffentlichung-des-mini-programs" aria-label="Permalink to “4.2 Formelle Veröffentlichung des Mini Programs”">​</a></h2><p>Nachdem die Erfahrungsversion gut läuft, können Sie dieses Snake-Mini-Program bereits in Ihrem eigenen WeChat spielen. Der nächste Schritt ist der Übergang von begrenzten Erfahrungsnutzern zu einem vollständig öffentlichen WeChat-Mini-Program.</p><p>Unterteilen wir dies in Schritte: Basisinformationen vervollständigen, Kategorie wählen, Registrierung abschließen, dann zur Überprüfung einreichen. Folgen Sie dieser Reihenfolge:</p><h3 id="_4-2-1-mini-program-veroffentlichungsablauf-betreten" tabindex="-1">4.2.1 Mini-Program-Veröffentlichungsablauf betreten <a class="header-anchor" href="#_4-2-1-mini-program-veroffentlichungsablauf-betreten" aria-label="Permalink to “4.2.1 Mini-Program-Veröffentlichungsablauf betreten”">​</a></h3><p>Kehren Sie zuerst zum WeChat Official Platform Backend zurück und melden Sie sich an. Finden Sie in der linken Navigation Einträge im Zusammenhang mit &quot;Version Management / Release&quot; (UI kann sich im Laufe der Zeit leicht ändern). Sie finden &quot;Mini Program Release Flow.&quot;</p><p>Nach dem Betreten zeigt der obere Bereich einen Fortschrittsbalken. Darunter sind Schritte aufgelistet wie:</p><ol><li>Mini Program Information</li><li>Mini Program Category</li><li>Operation Information / Filing</li><li>WeChat Verification (abhängig vom Entitätstyp)</li></ol><p>Zu Beginn beträgt der Fortschritt 0%. Mit jedem abgeschlossenen Schritt aktualisiert das System automatisch.</p><p><img src="'+x+'" alt=""></p><h3 id="_4-2-2-grundlegende-mini-program-informationen-ausfullen" tabindex="-1">4.2.2 Grundlegende Mini-Program-Informationen ausfüllen <a class="header-anchor" href="#_4-2-2-grundlegende-mini-program-informationen-ausfullen" aria-label="Permalink to “4.2.2 Grundlegende Mini-Program-Informationen ausfüllen”">​</a></h3><p>Der erste Schritt ist das Vervollständigen Ihrer Mini-Program &quot;Visitenkarte&quot;, also das, was Nutzer zuerst in WeChat sehen.</p><p>Auf der &quot;Mini Program Information&quot;-Seite müssen Sie normalerweise Folgendes ausfüllen/bestätigen:</p><ol><li>Mini-Program-Name Dieser erscheint in Suchergebnissen und im App-Header. Er hat Längenbeschränkungen und Namensregeln. Wählen Sie einen Namen, der die Funktion beschreibt und leicht zu merken ist.</li><li>Beschreibung / Einleitung Verwenden Sie ein oder zwei Sätze, um zu erklären, was dieses Mini Program tut, zum Beispiel: &quot;Ein Snake-Spiel, entwickelt mit KI-gestütztem Codieren, geeignet für schnelles Gelegenheitsspiel.&quot; Halten Sie die Beschreibung im Einklang mit der echten Funktionalität und vermeiden Sie übertriebenen Marketing-Text.</li><li>Icon und Screenshots <ol><li>Icon erfordert normalerweise ein quadratisches Bild mit PNG/JPG-Unterstützung und Größen-/Pixelbeschränkungen (Seitenregeln beachten). Verwenden Sie ein einfaches, kontrastreiches Icon.</li><li>Laden Sie mehrere Screenshots hoch wie Startseite, Spielseite, Einstellungsseite. Sie helfen Nutzern, den Inhalt zu verstehen.</li></ol></li><li>Sonstige Pflichtfelder Wie Tags und Service-Region, gemäß den Aufforderungen ausfüllen. Nur ein Prinzip: Alle Informationen müssen zur echten Funktionalität Ihres Snake-Mini-Programs passen.</li></ol><p><img src="'+N+'" alt=""></p><p>Nachdem alle Felder ausgefüllt sind, auf Speichern oder Weiter klicken. Der erste Schritt im Veröffentlichungsablauf ist abgeschlossen.</p><h3 id="_4-2-3-mini-program-servicekategorie-auswahlen" tabindex="-1">4.2.3 Mini-Program-Servicekategorie auswählen <a class="header-anchor" href="#_4-2-3-mini-program-servicekategorie-auswahlen" aria-label="Permalink to “4.2.3 Mini-Program-Servicekategorie auswählen”">​</a></h3><p>Nach den Basisinformationen führt Sie der Assistent zu &quot;Mini Program Category.&quot; Kategorie ist die Klassifizierung Ihrer App in WeChat, beeinflusst die Überprüfungsroute und spätere Anzeige/Betrieb.</p><p><img src="'+F+'" alt=""></p><p>Auf dieser Seite sehen Sie &quot;Add Category.&quot; Klicken Sie darauf und wählen Sie die passende Kategorie im System-Kategoriebaum, zum Beispiel:</p><p><img src="'+j+'" alt=""></p><ol><li>Wählen Sie &quot;Education&quot; als Hauptkategorie;</li><li>Dann wählen Sie eine spezifischere Unterkategorie wie &quot;Education Tools / Teaching Assistant.&quot; In diesem Beispiel wurden Bildungstools als Lernhilfe für Vibecoding ausgewählt.</li></ol><p>In Ihrem eigenen Projekt wählen Sie einfach die passendste Kategorie nach tatsächlichem Verwendungszweck.</p><p><img src="'+R+'" alt=""></p><p><img src="'+y+'" alt=""></p><p>Nach Bestätigung der Kategorie auf Speichern klicken. Wenn die Seite &quot;category created successfully&quot; anzeigt und Ihr neues Element auflistet, ist dieser Schritt abgeschlossen.</p><h3 id="_4-2-4-registrierungsinformationen-vervollstandigen" tabindex="-1">4.2.4 Registrierungsinformationen vervollständigen <a class="header-anchor" href="#_4-2-4-registrierungsinformationen-vervollstandigen" aria-label="Permalink to “4.2.4 Registrierungsinformationen vervollständigen”">​</a></h3><p>Als Nächstes fordert der Veröffentlichungsablauf &quot;Operation Information / Filing.&quot; Dies verifiziert die verantwortliche Entität hinter dem Mini Program.</p><p><img src="'+H+'" alt=""></p><p>Im Beispiel einer einzelnen Entität umfasst der Ablauf normalerweise:</p><ol><li>Registrierungstyp wählen Wählen Sie zwischen Typen wie &quot;Individual&quot; oder &quot;Enterprise&quot;, übereinstimmend mit Ihrer Registrierungsentität.</li><li>Entitätsinformationen ausfüllen Einschließlich Name, Ausweistyp, Ausweisnummer usw. Dies muss mit den Registrierungsinformationen übereinstimmen, sonst kann die Überprüfung abgelehnt werden.</li><li>Belegdokumente hochladen Normalerweise Ausweisfotos oder andere Nachweisdateien erforderlich, mit spezifischen Format-/Größen-/Klarheitsanforderungen auf der Seite. Klare Dateien vorbereiten und hochladen. <img src="'+O+'" alt=""></li></ol><p>Nach Einreichung geht das System in &quot;in Überprüfung&quot; und zeigt eine Nachricht wie &quot;Informationen eingereicht, bitte warten.&quot; Dies kann einige Zeit dauern. Sie können den Fortschritt jederzeit im Backend prüfen.</p><p><img src="'+U+'" alt=""></p><h3 id="_4-2-5-zur-uberprufung-einreichen-und-auf-formelle-veroffentlichung-warten" tabindex="-1">4.2.5 Zur Überprüfung einreichen und auf formelle Veröffentlichung warten <a class="header-anchor" href="#_4-2-5-zur-uberprufung-einreichen-und-auf-formelle-veroffentlichung-warten" aria-label="Permalink to “4.2.5 Zur Überprüfung einreichen und auf formelle Veröffentlichung warten”">​</a></h3><p>Wenn &quot;Mini Program Information&quot;, &quot;Category&quot; und &quot;Operation Information/Filing&quot; alle abgeschlossen sind, tun Sie die letzte Aktion: zur Überprüfung einreichen.</p><ol><li>Kehren Sie zur Veröffentlichungsablauf-Übersichtsseite zurück und bestätigen Sie, dass alle Punkte als abgeschlossen angezeigt werden, mit einem Fortschritt nahe 100%.</li><li>Klicken Sie auf &quot;Submit for Review&quot; (oder ähnliche Schaltfläche), um die aktuelle Entwicklungsversion dem WeChat-Überprüfungsteam einzureichen.</li><li>In &quot;Version Management&quot; wird der Status dieser Version zu &quot;Under Review.&quot; Nach Genehmigung wird er &quot;Published&quot; oder für &quot;Go Live&quot; verfügbar.</li></ol><p>Wenn die Registrierungsüberprüfung fehlschlägt, erhalten Entwickler möglicherweise einen Anruf, der die fehlgeschlagenen Teile spezifiziert.</p><p>Für die Registrierung erhalten Sie möglicherweise einen Verifizierungscode und einen Verifizierungslink vom Ministerium für Industrie und Informationstechnologie. Öffnen Sie den Link und füllen Sie Code + persönliche Informationen aus (Verifizierung 1 Tag gültig). Wenn die Registrierung bestanden wird, erhalten Sie E-Mail- und SMS-Benachrichtigung mit Registrierungsnummer. WeChat-Verifizierung: Einzelpersonen zahlen normalerweise 30 CNY, Unternehmen ca. 300 CNY. Die Gebühr ist unabhängig vom Genehmigungsergebnis nicht erstattungsfähig. Sie erhalten möglicherweise einen Verifizierungshinweis und einen Bestätigungsanruf.</p><p>Beim Einreichen zur Überprüfung laden Sie ein Betriebsvideo/-screenshots hoch und füllen die erforderlichen Informationen aus. Klicken Sie dann auf &quot;Submit Release&quot; für den formellen Start.</p><p><img src="'+G+'" alt=""></p><h1 id="_5-zusammenfassung" tabindex="-1">5. Zusammenfassung <a class="header-anchor" href="#_5-zusammenfassung" aria-label="Permalink to “5. Zusammenfassung”">​</a></h1><p>An diesem Punkt haben Sie einen vollständigen <strong>0-zu-1</strong> Mini-Program-Entwicklungsablauf abgeschlossen: vom Verstehen von Mini Programs über die Installation von Trae, HBuilderX und WeChat DevTools; von der Weitergabe Ihrer Idee an KI und dem Lassen &quot;Ziegel tragen&quot; im Code bis zum Spielen der ersten Snake-Version im Simulator; dann Verpacken als Erfahrungsversion, Abschließen von Registrierung/Überprüfung und dem Echtverfügbar-Machen in WeChat - Sie haben die vollständige Kette einmal persönlich durchlaufen.</p><p>Wichtiger noch: Sie haben dies nicht durch Auswendiglernen von Syntax erreicht. Sie haben es erreicht durch klares Ausdrücken von Anforderungen + effektive Kommunikation mit KI. Sie haben bereits erlebt: <strong>eine natürlichsprachige Anweisung kann KI Ihre Entwicklungsbedürfnisse sehr effektiv erfüllen lassen.</strong> Diese Fähigkeit ist nicht auf Snake beschränkt. Sie kann auf jedes Mini Program übertragen werden, das Sie später bauen wollen - Tools, Veranstaltungsseiten, Bildungs-Apps oder echte Arbeitsprojekte.</p><p>Wenn wir in eine <strong>allgemeine SOP</strong> zusammenfassen, sind es nur fünf Schritte: <strong>Eine kleine Anforderung klären -&gt; Projektgerüst in Trae bauen -&gt; Vibecoding + KI verwenden, um die erste Version zu erstellen -&gt; wiederholt spielen-testen und in WeChat DevTools verbessern -&gt; hochladen, registrieren, überprüfen und veröffentlichen.</strong> Jedes Mal, wenn Sie diese fünf Schritte wiederholen, erhalten Sie ein weiteres echtes Mini Program, das geöffnet und geteilt werden kann, und eine weitere Schicht an Zuversicht: &quot;Ich kann KI nutzen, um Ideen in Produkte zu verwandeln.&quot;</p><p>Als Nächstes können Sie weiterhin diese Snake-App polieren oder sie schließen und ein leeres Projekt mit Ihrer eigenen Idee starten. Egal was Sie bauen, merken Sie sich eines: Sie sind nicht mehr nur jemand, der &quot;etwas bauen will.&quot; Sie sind bereits ein Vibecoding-Entwickler, der den vollständigen Arbeitsablauf durchlaufen hat. Der Rest ist Wiederholung, bis diese Fähigkeit zur Gewohnheit wird.</p><h1 id="referenzen" tabindex="-1">Referenzen: <a class="header-anchor" href="#referenzen" aria-label="Permalink to “Referenzen:”">​</a></h1><ul><li><a href="https://zhuanlan.zhihu.com/p/1889401120939567074" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/1889401120939567074</a></li><li><a href="https://blog.csdn.net/2401_87407347/article/details/155193007" target="_blank" rel="noreferrer">https://blog.csdn.net/2401_87407347/article/details/155193007</a></li></ul>',195)])])}const ie=n(Z,[["render",L]]);export{ne as __pageData,ie as default};
